function BrokenUpload() {
  const [items, setItems] = useState([]);
  const [progress, setProgress] = useState(0);
  const [status, setStatus] = useState('idle');

  async function upload(file) {
    setStatus('loading'); setProgress(0);            // forget either -> inconsistent UI
    try {
      for await (const p of chunkedUpload(file)) setProgress(p);
      setItems((items) => [...items, file]);
      setStatus('done');                             // 3 setState calls, easy to miss one
    } catch (e) {
      setStatus('error');                            // progress left at 63% -> weird UI
    }
  }
}

// ✅ Reducer version: every transition is total and explicit
const initialState = { items: [], progress: 0, status: 'idle', error: null };

function uploadReducer(state, action) {
  switch (action.type) {
    case 'start':
      return { ...state, status: 'uploading', progress: 0, error: null };
    case 'progress':
      return { ...state, progress: action.value };
    case 'success':
      return { ...state, items: [...state.items, action.file], status: 'done' };
    case 'failure':
      return { ...state, status: 'error', error: action.error };
    case 'reset':
      return initialState;
    default:
      throw new Error('Unknown action: ' + action.type);   // fail loudly
  }
}

function Upload() {
  const [state, dispatch] = useReducer(uploadReducer, initialState);

  async function upload(file) {
    dispatch({ type: 'start' });
    try {
      for await (const p of chunkedUpload(file)) dispatch({ type: 'progress', value: p });
      dispatch({ type: 'success', file });
    } catch (error) {
      dispatch({ type: 'failure', error });
    }
  }
  // Invariants hold by construction: status/progress/error never disagree.
}

